//! Generated kernel symbol table (see kernel/ksyms.rs for the lookup logic
//! and kernel/build.rs for the generator).

use super::ksyms::{Ksym, KSYM_CAP};

// Generated by build.rs from the linked kernel ELF; size-stable across
// regeneration passes (see build.rs header comment).
include!(concat!(env!("OUT_DIR"), "/ksymtab.rs"));

/// Active suite name for FATAL markers (set by main from the boot cmdline).
static mut ACTIVE_SUITE: &str = "m0r";

pub fn set_active_suite(s: &'static str) {
    // SAFETY: single-CPU boot-time write before any consumer.
    unsafe { ACTIVE_SUITE = s };
}

pub fn active_suite() -> &'static str {
    // SAFETY: written once at boot, read afterwards.
    unsafe { ACTIVE_SUITE }
}

pub fn table() -> &'static [Ksym] {
    &KSYM_TABLE[..KSYM_COUNT]
}
